@RunWith(MockitoJUnitRunner.Silent.class)
public class RpcServletTest {}
/**************TEST SETUP BEGIN*************/
@Before
public void setUp() throws Exception{
        servlet = new RpcServlet(settings, gitblit);

        responseWriter = new StringWriter();
        PrintWriter pw = new PrintWriter(responseWriter);
        when(response.getWriter()).thenReturn(pw);

        // Default: RPC servlet enabled
        when(settings.getBoolean(Keys.web.enableRpcServlet, true)).thenReturn(true);
        when(settings.getBoolean(Keys.web.enableRpcManagement, false)).thenReturn(false);
        when(settings.getBoolean(Keys.web.enableRpcAdministration, false)).thenReturn(false);
        when(settings.getString(Keys.web.canonicalUrl, null)).thenReturn("http://localhost");

        // Admin user setup
        adminUser = new UserModel("admin");
        adminUser.canAdmin = true;

        // Normal user setup
        normalUser = new UserModel("user");
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void testListRepositories_withRepos_returnsCloneUrls() throws Exception{
        when(request.getParameter("req")).thenReturn("LIST_REPOSITORIES");
        when(request.getParameter("name")).thenReturn(null);
        when(request.getUserPrincipal()).thenReturn(adminUser);
        when(request.getRemoteAddr()).thenReturn("127.0.0.1");

        RepositoryModel repo = new RepositoryModel("test.git", "", "admin", null);
        when(gitblit.getRepositoryModels(adminUser)).thenReturn(Arrays.asList(repo));

        servlet.doGet(request, response);

        String body = responseWriter.toString();
        assertTrue("Expected clone URL in response", body.contains("test.git"));
    }
/**************TEST METHOD END*************/


